import{_ as s,o as t,c as a,a6 as n}from"./chunks/framework.BBdhcoHf.js";const k=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md","lastUpdated":1772916561000}'),i={name:"guide/concepts.md"};function o(d,e,r,c,h,l){return t(),a("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /guide/concepts.md for this page in Markdown format</div><h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to “Core Concepts”">​</a></h1><p>This page explains the mental model behind Sideband. You don&#39;t need to understand all of it to get started — the <a href="./">quick start</a> gets you running in five lines — but understanding the concepts helps when you hit edge cases.</p><hr><h2 id="peers" tabindex="-1">Peers <a class="header-anchor" href="#peers" aria-label="Permalink to “Peers”">​</a></h2><p>A <strong>Peer</strong> is a long-lived connection endpoint. You create one, connect it, and use it until you disconnect. One peer = one logical connection.</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> peer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createPeer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ endpoint: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ws://localhost:8080&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> peer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ... use peer</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> peer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">disconnect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>On the server side, <code>listen()</code> accepts incoming connections. Each accepted connection is an <code>ConnectedPeer</code> — the same abstraction, but with no <code>connect()</code> (the server doesn&#39;t initiate).</p><hr><h2 id="sessions-and-negotiators" tabindex="-1">Sessions and Negotiators <a class="header-anchor" href="#sessions-and-negotiators" aria-label="Permalink to “Sessions and Negotiators”">​</a></h2><p>A <strong>session</strong> is what happens when the transport connects. Before any application messages flow, both sides run a <strong>negotiator</strong> — a protocol handshake that establishes identity, capabilities, and optionally an encrypted channel.</p><p>The default negotiator (<code>SBP</code>) just exchanges peer IDs and capabilities. The SBRP negotiator adds E2EE on top: same API, different negotiator option.</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Plain (no encryption)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createPeer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ endpoint: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ws://...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// E2EE via relay (SBRP)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createPeer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  endpoint: relayUrl, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// from POST /api/sessions</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  negotiator: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">relayClientNegotiator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    daemonId,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    sessionToken,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    identityKeyStore,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Everything above the negotiator — RPC, events, reconnection — is identical regardless of which session layer is active.</p><hr><h2 id="subjects-and-channels" tabindex="-1">Subjects and Channels <a class="header-anchor" href="#subjects-and-channels" aria-label="Permalink to “Subjects and Channels”">​</a></h2><p>Every message frame carries a <strong>subject</strong> — a routing label that determines how the runtime dispatches it:</p><table tabindex="0"><thead><tr><th>Subject</th><th>Semantics</th></tr></thead><tbody><tr><td><code>rpc</code></td><td>Request/response — exactly one handler, exactly one reply</td></tr><tr><td><code>event</code></td><td>Fire-and-forget — all matching handlers called</td></tr><tr><td><code>stream</code></td><td>Reserved (v2)</td></tr><tr><td><code>app/*</code></td><td>Custom application protocols (user-defined)</td></tr></tbody></table><p><code>rpc</code> and <code>event</code> are the two active built-in channels. <code>stream</code> is reserved for future use. The <code>app/*</code> namespace is open for application-defined protocols.</p><p>Method and event names live inside the frame payload (the RPC envelope), not in the subject. The subject identifies the message class; the envelope identifies the operation.</p><hr><h2 id="state-machine" tabindex="-1">State Machine <a class="header-anchor" href="#state-machine" aria-label="Permalink to “State Machine”">​</a></h2><p>A peer moves through states in a defined order. Understanding states matters when you handle errors or want to react to connection changes.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>idle → connecting → negotiating → active</span></span>
<span class="line"><span>         ↑                          ↓</span></span>
<span class="line"><span>         └──── reconnecting ────────┘</span></span>
<span class="line"><span>active ↔ paused  (SBRP only: relay lost upstream)</span></span>
<span class="line"><span>any → closed  (terminal)</span></span></code></pre></div><p>Reconnection always goes through the full <code>connecting → negotiating → active</code> cycle — session state is re-established, not resumed from mid-handshake.</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>idle</code></td><td>Not connected. Initial state.</td></tr><tr><td><code>connecting</code></td><td>Transport connect in progress.</td></tr><tr><td><code>negotiating</code></td><td>Transport open; handshake in progress.</td></tr><tr><td><code>active</code></td><td>Ready to send and receive.</td></tr><tr><td><code>paused</code></td><td>SBRP session pause — daemon disconnected; relay holds WebSocket, client buffers locally.</td></tr><tr><td><code>reconnecting</code></td><td>Waiting before retry attempt.</td></tr><tr><td><code>closed</code></td><td>Terminal. No further transitions.</td></tr></tbody></table><p><code>peer.ready</code> is <code>true</code> only in <code>active</code>. <code>peer.connected</code> is <code>true</code> in both <code>active</code> and <code>paused</code>.</p><hr><h2 id="rpc" tabindex="-1">RPC <a class="header-anchor" href="#rpc" aria-label="Permalink to “RPC”">​</a></h2><p>RPC follows a request/response pattern. Each call is correlated by a <code>cid</code> (correlation ID) assigned at send time. With <code>onDisconnect: &quot;pause&quot;</code>, the call intent is buffered across reconnections and sent with a fresh <code>cid</code> once the session is restored. See the <a href="./rpc">RPC guide</a>.</p><hr><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h2><p>Events are fire-and-forget notifications. Subscribers use NATS-style dot-separated names with <code>*</code> (one segment) and <code>&gt;</code> (one or more segments) wildcards. See the <a href="./events">Events guide</a>.</p><hr><h2 id="e2ee-and-identity" tabindex="-1">E2EE and Identity <a class="header-anchor" href="#e2ee-and-identity" aria-label="Permalink to “E2EE and Identity”">​</a></h2><p>In SBRP mode, the daemon has a persistent Ed25519 identity keypair. The client pins the daemon&#39;s public key fingerprint on first connection (TOFU — Trust On First Use). Subsequent connections verify against the pinned key; a mismatch is fatal (not retryable). The relay never sees plaintext — all frame content is ChaCha20-Poly1305 encrypted end-to-end.</p><p>See the <a href="./e2ee">E2EE guide</a> for setup.</p>`,37)])])}const g=s(i,[["render",o]]);export{k as __pageData,g as default};
